   342	            String[] suffixes = {"Like", "Gt", "Lt", "Ge", "Le", "Ne", "In", "NotIn", "Between", "NotBetween", "IsNull", "IsNotNull"};
   343	            for (String suffix : suffixes) {
   344	                if (fieldPart.endsWith(suffix)) {
   345	                    fieldPart = fieldPart.substring(0, fieldPart.length() - suffix.length());
